  "id": "T-289",
  "milestone": "M2",
  "title": "The captain's board pages are ported from the approved v2 prototype HTML and CSS, so the board looks like the design the captain approved",
  "public_title": "Port the board pages from the approved v2 prototype",
  "depends_on": [
    "T-298"
  ],
  "design": {
    "mode": "prototype",
    "prototype": "state/prototypes/board-v2",
    "approved_by": "captain 2026-10-07 chat approval",
